using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using VisionCore;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.DistortionCalibration;
static class Program{
 static int checks;static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine($"PASS {++checks}: {text}");}
 static readonly List<object> reports=[];
 static void Compare(string stage,int type,int index,DistortionCalibrationRecognitionResult actual,JsonElement original){var expected=original.GetProperty("points").EnumerateArray().ToArray();bool ids=actual.Points.Count==expected.Length&&actual.Points.Select((p,i)=>p.GridX==expected[i][0].GetInt32()&&p.GridY==expected[i][1].GetInt32()).All(x=>x);bool bits=ids&&actual.Points.Select((p,i)=>BitConverter.SingleToInt32Bits(p.X)==BitConverter.SingleToInt32Bits(expected[i][2].GetSingle())&&BitConverter.SingleToInt32Bits(p.Y)==BitConverter.SingleToInt32Bits(expected[i][3].GetSingle())).All(x=>x);int first=-1;for(int i=0;i<Math.Min(actual.Points.Count,expected.Length);i++){var p=actual.Points[i];if(p.GridX!=expected[i][0].GetInt32()||p.GridY!=expected[i][1].GetInt32()||BitConverter.SingleToInt32Bits(p.X)!=BitConverter.SingleToInt32Bits(expected[i][2].GetSingle())||BitConverter.SingleToInt32Bits(p.Y)!=BitConverter.SingleToInt32Bits(expected[i][3].GetSingle())){first=i;break;}}
 reports.Add(new{stage,type,index,actual.ErrorCode,actualCount=actual.Points.Count,originalCount=expected.Length,idsAndOrder=ids,floatBitsExact=bits,firstDifference=first,actualFirst=actual.Points.Take(3).ToArray(),originalFirst=expected.Take(3).Select(x=>x.Clone()).ToArray()});File.WriteAllText("analysis/distortion-calibration/encoded68-reopen/differences.json",JsonSerializer.Serialize(reports,new JsonSerializerOptions{WriteIndented=true}));Check(actual.ErrorCode==0&&ids&&bits,$"original independent board oracle {type}/{stage}/{index}: counts{actual.Points.Count}/{expected.Length}, first{first}, code{actual.ErrorCode:x}");Check(actual.GridPitch==1,"distortion unit index pitch retained");}
 static GrayImage Load(string path){var image=new FormatConvertedBitmap(BitmapFrame.Create(new Uri(Path.GetFullPath(path))),PixelFormats.Gray8,null,0);var pixels=new byte[image.PixelWidth*image.PixelHeight];image.CopyPixels(pixels,image.PixelWidth,0);return new(image.PixelWidth,image.PixelHeight,pixels);}
 static DistortionCalibrationRecognitionResult RuntimeRecognition(GrayImage source,int type,JsonElement row){var plugin=new DistortionCalibrationPlugin();var values=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());values["CalibBoardType"]=JsonSerializer.SerializeToElement(type);var roi=new RoiDocument("existing-native-roi",RoiKind.Rectangle,row.GetProperty("cx").GetSingle(),row.GetProperty("cy").GetSingle(),row.GetProperty("width").GetSingle(),row.GetProperty("height").GetSingle(),AngleDegrees:row.GetProperty("angle").GetSingle());const BindingFlags flags=BindingFlags.Static|BindingFlags.NonPublic;var crop=typeof(DistortionCalibrationPlugin).GetMethod("Crop",flags)!.Invoke(null,[source,new[]{roi}]);var context=new ModuleExecutionContext("encoded68",Environment.CurrentDirectory,new Dictionary<string,PortValue>{{"InputImage",PortValue.Image(source)}},values);return (DistortionCalibrationRecognitionResult)typeof(DistortionCalibrationPlugin).GetMethod("Recognize",flags)!.Invoke(null,[source,crop,context,CancellationToken.None])!;}
 [STAThread]static int Main(){try{Directory.CreateDirectory("analysis/distortion-calibration/encoded68-reopen");using var evidence=JsonDocument.Parse(File.ReadAllText("docs/plugins/calibration-board-encoded-roi-rotated-evidence.json"));var images=evidence.RootElement.GetProperty("sources").EnumerateArray().Where(x=>x.GetProperty("boardType").GetInt32() is 6 or 8).ToDictionary(x=>x.GetProperty("boardType").GetInt32(),x=>Load(x.GetProperty("image").GetString()!));
 foreach(string line in File.ReadLines("docs/plugins/calibration-board-encoded-full-output-fixtures.jsonl")){using var doc=JsonDocument.Parse(line);var row=doc.RootElement;int type=row.GetProperty("boardType").GetInt32();if(type is not(6 or 8))continue;Compare("full-raw",type,0,DistortionCalibrationRecognition.Recognize(images[type],type),row);}
 foreach(string line in File.ReadLines("docs/plugins/calibration-board-encoded-axis-output-fixtures.jsonl")){using var doc=JsonDocument.Parse(line);var row=doc.RootElement;int type=row.GetProperty("boardType").GetInt32();if(type is not(6 or 8))continue;Compare("actual-runtime-axis",type,row.GetProperty("index").GetInt32(),RuntimeRecognition(images[type],type,row),row);}
 foreach(string line in File.ReadLines("docs/plugins/calibration-board-encoded-roi-rotated-fixtures.jsonl")){using var doc=JsonDocument.Parse(line);var row=doc.RootElement;int type=row.GetProperty("boardType").GetInt32(),index=row.GetProperty("index").GetInt32();if(type is not(6 or 8)||index>1)continue;Compare("actual-runtime-mask",type,index,RuntimeRecognition(images[type],type,row),row);}
 if(Environment.GetCommandLineArgs().Contains("--runtime-smoke"))foreach(int type in new[]{6,8}){
 var plugin=new DistortionCalibrationPlugin();var values=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());values["CalibBoardType"]=JsonSerializer.SerializeToElement(type);values["CorrectModel"]=JsonSerializer.SerializeToElement(1);values["CalibBoardWeightFun"]=JsonSerializer.SerializeToElement(1);values["DistortionEvaluationEnable"]=JsonSerializer.SerializeToElement(true);values["OutputPostCorrectionEnable"]=JsonSerializer.SerializeToElement(true);values["CalibPathName"]=JsonSerializer.SerializeToElement(Path.GetFullPath($"analysis/distortion-calibration/encoded68-reopen/runtime-{type}.iccal"));
 var result=plugin.CreateRuntime().ExecuteAsync(new($"runtime-{type}",Environment.CurrentDirectory,new Dictionary<string,PortValue>{{"InputImage",PortValue.Image(images[type])}},values),default).GetAwaiter().GetResult();
 File.WriteAllText($"analysis/distortion-calibration/encoded68-reopen/runtime-{type}.json",JsonSerializer.Serialize(new{type,result.Status,result.NativeErrorCode,result.Message,outputs=result.Outputs.Keys,correctedCount=result.Outputs.TryGetValue("CalibPointNum",out var n)?n.As<long>():0,nativeCorrectedOracleAvailable=false},new JsonSerializerOptions{WriteIndented=true}));
 Check(result.Status==ModuleStatus.Success,$"real6/8 full tool solve/warp/corrected-redetection smoke {type}: {result.NativeErrorCode:x} {result.Message}");Check(result.Outputs.ContainsKey("PostCorrectionImage")&&result.Outputs.ContainsKey("CalibPointX"),"real corrected display outputs exist, not claimed native corrected numeric oracle");
 }
 Console.WriteLine($"PASS {checks}: distortion6/8 independent original full/axis/mask points, IDs, order and float bits; no new native run.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
